using static StrataLint.Scribe.FormulaDsl;
using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.FibonacciAtomic.Observer.Constructor;

internal sealed class NativePositivePotentialCoverDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Arith/FibonacciAtomic/Observer/Constructor/NativePositivePotentialCover.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Signed source cycles and minimum natural block bases",
        H("The total named source family"), Blocks(
            Paragraph(Text("Let p present the entire finite set X of declared names, B be a finite list of selected BranchEquation cases, and S be the actual successful free-shape unifier of shapeEquations(B). The assignment s=action(p,S) retains every named term, including unused names. A residual occurrence records its name, its ordered address and its residual sort. The list occurrenceVertices(p,s) includes isolated occurrences. An occurring sort j has at least one such vertex. Decidable equality on X supports finite sort selection and equality tests on occurrence labels.")),
            Entry("sortEdges", "The actual sort edges",
                "sortEdges(B,s,j) filters sourceOffsetEdges(B,s) by the sort of the left endpoint. It preserves list order, every repeated equation and every parallel edge. For a successful unifier, both endpoints are actual vertices of the same sort. A source shift contributes its original nonnegative integer offset. Ordinary and equality comparisons contribute zero. Explicit primitive ranks are separately decorated at their named addresses. The complete comparison inventory below retains scalar equations r=r'+d and r=d and one shared natural collapse parameter with ranks r,r+1,r+2. Its block projection is exactly sourceOffsetEdges; it does not solve the independent scalar equations."),
            Entry("signedGraph", "Both orientations retain each edge identity",
                "For each indexed sort edge U=V+d, signedGraph has a forward edge from V to U and a reverse edge from U to V. The Boolean orientation is part of the edge identity. Thus zero offsets, repeated edges and parallel edges remain explicit, and reversing an edge changes only its orientation and weight."),
            Entry("signedWeight", "The signed offset",
                "The forward weight is d and the reverse weight is -d. A walk has the sum of its oriented edge weights. For a potential delta satisfying every original edge, the sum is delta(finish)-delta(start), so two paths with the same endpoints have the same sum."),
            Entry("ZeroCycles", "Zero signed sum on every closed walk",
                "ZeroCycles asserts that every closed walk at every occurrence has weight zero. The condition refers to the actual sort edge list rather than an epoch or head-power graph. Vertices without incident edges contribute only empty walks."),
            Entry("Potential", "Integer differences on the source edges",
                "Potential(B,s,j,delta) states delta(U)=delta(V)+d for every edge U=V+d of the selected sort. Pairing both orientations identifies this exact equality with the inequalities of Maths.MaxPlusPotential.IsPotential. The finite supplier theorem exists_isPotential_iff_forall_closedWalk_nonpos supplies the existence criterion. The actual witness used for minimum normalization is computedSourcePotential on this source graph; its correctness reuses the existing cycle-pruning supplier."),
            Entry("BlockSolution", "Natural ranks on an arbitrary leaf carrier",
                "A block valuation u assigns a natural rank u(U,l) to each occurrence U and each leaf l. BlockSolution imposes the original signed integer equation at every leaf and every selected edge. The carrier L may be any type; no cardinality bound is imposed. Detecting inconsistency requires L to be nonempty. In particular this includes every nonempty finite ground-shape leaf set."),
            Entry("signedEdges", "Enumerate every signed source edge",
                "signedEdges enumerates both Boolean orientations for every index of sortEdges. Indices preserve repeated and parallel source comparisons. No vertex enumeration or connected-component choice is an input."),
            Entry("sourceRelaxation", "Finite integer relaxation on the actual source graph",
                "At round zero every occurrence has value zero. Each successive round takes the maximum of zero and every previous-round source value plus the actual signed edge weight whose target is this occurrence. The recurrence uses finite lists, decidable equality and integer arithmetic. A round is attained by a real walk, and bounds every real walk of that length. The existing SupplierDual cycle-pruning theorem reduces an arbitrary candidate to a walk with no repeated visited vertex, hence no repeated signed edge."),
            Entry("computedSourcePotential", "An executable source potential candidate",
                "For k indexed source edges the candidate runs exactly 2k relaxation rounds, the number of signed edges. It takes only B,s,j and the queried occurrence. It requires no cycle proof, solution, potential witness, ground filling or classical choice at runtime. If every signed cycle has weight zero, cycle pruning bounds a maximizing extended walk by the signed-edge count and proves both oriented inequalities. Their conjunction is precisely every original integer source offset equation. The function is total also for inconsistent graphs; correctness is asserted only under ZeroCycles."),
            Entry("checkSourceConsistency", "Decide consistency by exact finite edge equations",
                "The Boolean checker computes the 2k-round candidate and tests delta(U)=delta(V)+d on every entry of sortEdges. It uses only finite list traversal, the supplied decidable equality on names, and exact integer arithmetic. Repeated and parallel edges are tested separately. No bound on offsets, vertex names, ordered addresses or residual sorts is imposed. The empty edge list is accepted; isolated vertices retain candidate value zero."),
            Describe.Lean(DescribeId.Create("source-consistency-iff"),
                DeclarationHandle.Create(Prefix + "source_consistency_iff"),
                H("The executable checker is equivalent to the original closed-walk criterion"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For every finite branch list B, every substituted term family s, and every residual sort j, checkSourceConsistency(B,s,j)=true if and only if ZeroCycles(B,s,j). Acceptance verifies every exact source edge equation for computedSourcePotential. The resulting potential telescopes on every original signed closed walk, proving soundness. Conversely, zero sums on all closed walks make the finite relaxation candidate a potential by cycle pruning, so every checked edge equation holds. This proves completeness for the original labelled graph, including arbitrary repeated or parallel signed edges, zero offsets, empty lists and isolated occurrences. No successful unifier or native solution is required for this equivalence."))), DescribeRole.Theorem),
            Entry("effectiveSourcePotential", "An effective decision returns a certified potential",
                "The effective function runs checkSourceConsistency and returns some computedSourcePotential together with its exact Potential proof when accepted, or none when rejected. Proofs are erased during execution. The checker equivalence makes rejection equivalent to failure of the original ZeroCycles condition. Minimum normalization below obtains its potential and edge proof from this returned value; the same potential therefore supplies canonical and native block recovery."),
            Describe.Lean(DescribeId.Create("source-sort-minimum-natural-base"),
                DeclarationHandle.Create(Prefix + "source_sort_minimum_base"),
                H("Minimum-potential normalization classifies every natural block solution"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For every p,B,S,j as above with at least one occurrence of j, the theorem has two conclusions. If ZeroCycles fails, then for every nonempty type L and every natural block valuation u on L, BlockSolution fails. If ZeroCycles holds, there exist one integer potential delta equal to computedSourcePotential(B,s,j), one actual vertex b of sort j, and natural offsets a(U), independent of L and u. The chosen b minimizes delta among all actual vertices of sort j, a(b)=0, and a(U)=delta(U)-delta(b) as an integer at every such vertex. For every L, including the empty type, and every u, BlockSolution holds exactly when u(U,l)=u(b,l)+a(U) for every actual vertex U of sort j and every l. Consequently every natural base function gives a solution by that formula, with arbitrary values outside the selected sort.")),
                    Paragraph(Text("A nonempty leaf valuation at any fixed leaf gives an integer potential, which telescopes around closed walks and excludes nonzero cycle sums. Conversely the exact finite consistency checker accepts when cycles vanish, and effectiveSourcePotential returns the certified relaxation candidate used for minimum normalization. Connectivity of the actual MGU source graph identifies all vertices of the same residual sort. Subtracting any two edge potentials gives a constant along this equivalence closure. Choosing a minimum on the finite vertex list makes every potential difference nonnegative; exact integer-to-natural conversion then gives the natural rank classification. The reverse implication uses the actual endpoints of every source edge and the same potential equation. This argument includes isolated unused names, empty branch lists, zero offsets, repeated and parallel constraints. If no sort occurs, the theorem is unnecessary and there is no block-base factor.")),
                    Paragraph(Text("This theorem establishes the signed-cycle and natural-rank classification using a terminating potential computation on the original source graph. The canonical recovery theorem below first presents the rank-to-code step with its precise inputs. The native source theorem then derives those inputs from an original native solution and its actual branch, without assuming a BlockSolution or desired subtree identities. The finite positive image cover and signed pullback are separate results."))), DescribeRole.Theorem)
            ,Entry("Leaves", "Nonempty finite leaves of an ordered shape",
                "The leaves of a primitive shape form Unit; leaves of a pair form the disjoint sum of the two child leaf sets. These types are finite and nonempty. Distinct positions remain distinct even when their ranks are equal."),
            Entry("fill", "Fill the same ground shape with natural ranks",
                "fill(T,r) puts rank r(l) at each ordered leaf l of T. Adding a natural number a to every rank gives exactly shiftCode(a,fill(T,r)). This is a structural property of finite ordered codes, with no normality assumption."),
            Describe.Lean(DescribeId.Create("source-canonical-block-recovery"),
                DeclarationHandle.Create(Prefix + "source_canonical_block_recovery"),
                H("Recover normal occurrence blocks by the actual native shifts"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For every actual successful source unifier and occurring sort with zero signed cycle sums, there are one actual base vertex b and natural offsets a with a(b)=0, independent of all ground fillings. The base minimizes computedSourcePotential over every actual occurrence of this sort, and a(o) equals its exact integer potential difference from b. Let T be any finite ground shape, u a natural rank valuation on its nonempty leaf type satisfying BlockSolution, and C the entire family of normal named codes. Suppose that at every actual occurrence v of this sort, the subtree of C(v.name) at v.address is exactly fill(T,u(v)). Then fill(T,u(b)) is normal. For every actual v of the sort, fill(T,u(v)) equals shiftCode(a(v),fill(T,u(b))); its expansion is the actual native substitution iterated a(v) times on the expansion of the base; and rankInverse(a(v),u(v,l)) is exactly some(u(b,l)) at every leaf.")),
                    Paragraph(Text("The rank classification supplies the same minimum vertex for all fillings. Normality descends along the actual ordered subtree address in the normal named code. Structural filling converts the pointwise rank equation to literal code translation. NativeFiniteNormalInversion.shift_expand gives the native equality, and exact_natural_rank_inverse gives every exact inverse rank without truncated subtraction. No desired normal base, integer potential or reconstruction equality is assumed. The concrete subtree identities and BlockSolution are hypotheses of this intermediate theorem. They are derived automatically on the live proof path of native_source_block_recovery."))), DescribeRole.Theorem),
            Entry("ScalarPosition", "Separate scalar positions",
                "A scalar label consists of a declared name and its ordered address. Every explicit primitive occurrence gets its own label, while repeated uses of one name reuse the same decorated term. Residual blocks retain the existing name, address and sort labels."),
            Entry("RankExpression", "Natural scalar variables and constants",
                "A rank expression is either a separately addressed natural scalar or a supplied natural constant. Its value is evaluated independently of the residual block valuation."),
            Entry("DecoratedTerm", "A complete decoration of each named term",
                "The decorated syntax distinguishes explicit scalar leaves, residual block leaves and ordered pairs. Erasure retains the original primitive Boolean or residual sort. Evaluation substitutes a natural rank at each scalar leaf and an ambient finite code at each residual occurrence."),
            Entry("scalarDecorateFrom", "Decorate every explicit and residual position",
                "Structural descent extends the address by false on the left and true on the right. It labels every primitive occurrence and every residual occurrence without identifying positions."),
            Entry("scalarDecorate", "One shared decoration per original name",
                "scalarDecorate(s,x) starts at the empty address in the entire substituted term s(x). It includes unused names and has no depth bound."),
            Entry("ComparisonInventory", "Scalar and block equations in one finite inventory",
                "A scalar comparison states an exact integer equation r=r'+a for natural ranks and the original natural shift a. A supplied constant gives r=d. A block comparison states literal code translation by the same shift. Pair comparisons retain both child inventories; mismatched scalar, block or pair constructors are incompatible. Under the successful shape unifier the compared erased terms agree, so no mixed scalar/block equation is generated.", "comparison-inventory-type"),
            Entry("comparisonInventory", "Recursive comparison with both directions proved",
                "Matching scalar leaves emit their scalar offset equation; matching residual leaves emit the original block offset equation; matching pairs recursively compare both ordered children. For equal erased terms, the inventory holds exactly when the evaluated left code is the supplied shift of the evaluated right code. This equivalence is proved for arbitrary independent natural scalar and code-block assignments."),
            Entry("BranchInventory", "The actual natural collapse witness",
                "A branch inventory is a comparison or a collapse family quantified existentially over one natural number. A collapse uses the same witness n in its three equations at ranks n+1,n,n+2. Separate collapse equations retain their own witnesses.", "branch-inventory-type"),
            Entry("branchInventory", "All original comparison constructors",
                "Primitive equations compare with their supplied rank. Shifts retain their original offset. Ordinary constructor and equality comparisons use zero offset. Collapse compares all three named terms against the three scalar constants determined by its single natural witness. The original branch list retains repeated equations."),
            Describe.Lean(DescribeId.Create("source-decorated-comparison-equivalence"),
                DeclarationHandle.Create(Prefix + "source_decorated_comparison_equivalence"),
                H("The complete decorated system is equivalent to the original branch system"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For the actual successful shape unifier S of the entire finite branch list B, and for every independent assignment of natural scalar values and ambient residual codes, the complete branch inventories hold exactly when every original BranchEquation holds on the reconstructed named codes. Both implications retain primitive constants, scalar offsets, ordinary zero offsets and each original existential natural collapse witness. No scalar equivalence or scalar consistency is assumed.")),
                    Paragraph(Text("The theorem also identifies the concatenation of every inventory's block edges with exactly sourceOffsetEdges(B,action(p,S)), including repeated and parallel edges. The recursive projection erases only scalar equations. Collapse has no residual edge. Thus the same block equations feed the computed source potentials and minimum normalization above; no replacement graph is introduced. Successful unification supplies the erased comparison equalities; a structural equivalence handles each comparison, and then each original constructor and the entire branch list. Empty lists and empty declared families remain in scope."))), DescribeRole.Theorem),
            Entry("sourceScalarRanks", "Read actual scalar ranks at their original addresses",
                "At a valid primitive address sourceScalarRanks reads its exact natural rank. A default zero is used only elsewhere. Structural reconstruction proves that evaluating every separately decorated named term with these scalar ranks and occurrenceCode gives the entire original named code, so no default affects an explicit primitive position."),
            Entry("occurrenceCode", "Read the actual occurrence subtree",
                "occurrenceCode(C,o) reads the code subtree of the original named code C(o.name) at o.address, using a fixed default only at invalid addresses. The native source theorem proves every MGU occurrence address is valid before using its code; the default contributes no valid block."),
            Describe.Lean(DescribeId.Create("native-source-block-recovery"),
                DeclarationHandle.Create(Prefix + "native_source_block_recovery"),
                H("Original native solutions supply their own canonical blocks"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For every finite presentation p of the entire declared named family X, original equation list E and actual native solution v, the theorem selects B in branches(E) and an actual successful shape unifier S. Every original selected BranchEquation.Holds remains true of C(x)=encode(v(x)). The theorem reconstructs every original named code from its separately addressed scalar ranks and actual occurrence blocks, and proves the complete branch inventory on these same values. Thus primitive constants, scalar offsets, full block shifts, ordinary zero offsets, equalities, and collapse witnesses r with ranks r,r+1,r+2 remain attached to this same actual solution. For every occurring residual sort there is an actual base occurrence b minimizing computedSourcePotential and natural offsets a(o)=computedSourcePotential(o)-computedSourcePotential(b), with a(b)=0. Its actual occurrenceCode is normal, and every actual occurrence block is literally shiftCode(a(o),occurrenceCode(C,b)); expansion gives the identical original native substitution iterated a(o) times.")),
                    Paragraph(Text("The shape factorization is supplied by native_branch_reduction. A structural fit of the decorated MGU terms to C extracts each actual source-offset equation from BranchEquation.Holds, using the same comparison recursion. Descent through the factorized shape proves valid code subtrees and the common ground shape. Reading their ordered leaf ranks gives BlockSolution and the exact fill identities. A nonempty leaf detects zero signed cycles. These derived facts consume source_canonical_block_recovery, whose base and offsets come from source_sort_minimum_base and its computed potential. No BlockSolution, potential, desired subtree identity or desired reconstruction is an external premise. Isolated occurrences, unused names and repeated edges remain in scope. If no sort occurs the conclusion is the empty universal family. This theorem does not assert the image-cover or Theorem 3.2."))), DescribeRole.Theorem)

        )));

    private static DocumentBlock Entry(string name, string title, string prose, string? id = null) =>
        Describe.Lean(DescribeId.Create("source-potential-" + (id ?? name.ToLowerInvariant())),
            DeclarationHandle.Create(Prefix + name), H(title), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), DescribeRole.Definition);
}
